insert into public.events (slug, title, flyer_url, flyer_width, flyer_height, sessions, venue, address, summary, link) values
('freedom-fest-2026', 'Freedom Fest', '/images/flyers/freedom-fest-2026.webp', 933, 1400, '[{"start":"2026-11-07T13:00:00-05:00"}]'::jsonb, 'Downtown on the Plaza', 'Lumberton, NC', 'A day of faith, music, and freedom. Brandon Hamilton brings the Word, with worship from The United Worship Band, Song Byrd Ministries, food trucks, and local vendors.', null),
('fayetteville-cares', 'Fayetteville Cares', '/images/flyers/fayetteville-cares.webp', 1050, 1400, '[{"start":"2026-09-15T10:00:00-04:00","end":"2026-09-15T11:30:00-04:00"},{"start":"2026-10-20T10:00:00-04:00","end":"2026-10-20T11:30:00-04:00"},{"start":"2026-11-17T10:00:00-05:00","end":"2026-11-17T11:30:00-05:00"}]'::jsonb, 'Fayetteville Cares', '128 South King Street, Fayetteville, NC', 'Hope, encouragement, and recovery support on the third Tuesday of each month. Light snacks, a hope-filled message, and resources for those who want them. Everyone is welcome. Come as you are.', null),
('cape-fear-outreach-2026', 'Community Outreach Day', '/images/flyers/cape-fear-outreach-2026.webp', 1062, 1394, '[{"start":"2026-10-15T10:00:00-04:00","end":"2026-10-15T14:00:00-04:00"}]'::jsonb, 'Kingdom Impact Global Ministries', '2503 Murchison Road, Fayetteville, NC 28301', 'Hosted by the Cape Fear Valley Community Paramedic Program, with free food, resources, and health information. Fire4Prodigals was there for prayer, encouragement, and resource connections.', null),
('restored-table-revival-2026', 'The Restored Table Spring Revival', '/images/flyers/restored-table-revival-2026.webp', 1050, 1400, '[{"start":"2026-04-17T19:00:00-04:00"},{"start":"2026-04-18T18:00:00-04:00"},{"start":"2026-04-19T10:00:00-04:00"}]'::jsonb, 'The Restored Table', '12560 NC-210, Benson, NC 27504', 'Three nights of worship and preaching with Drew Anderson and Pastor Josh Harris.', null),
('celebrate-recovery-2026', 'Celebrate Recovery: Brandon''s Testimony', '/images/flyers/celebrate-recovery-2026.webp', 1080, 1080, '[{"start":"2026-04-10T19:00:00-04:00"}]'::jsonb, 'MidPoint Church', '', 'Brandon Hamilton shared his testimony at Celebrate Recovery. Snacks at 6:30, childcare provided.', null),
('overdose-awareness-day-2026', 'Overdose Awareness Day', '/images/flyers/overdose-awareness-day-2026.webp', 1120, 1400, '[{"start":"2026-08-29T13:00:00-04:00","end":"2026-08-29T17:00:00-04:00"}]'::jsonb, 'Changing Paths NC II', '205 Martha Ln, Clinton, NC 28328', 'Remember. Support. Prevent. Brandon & Melody Hamilton spoke at this free community day with music, resources, bouncy houses, ice cream, and a butterfly release for those lost to overdose.', null),
('lumberton-plaza-outreach-2026', 'Community Outreach at Lumberton Plaza', '/images/flyers/lumberton-plaza-outreach-2026.webp', 1119, 1400, '[{"start":"2026-05-30T11:00:00-04:00","end":"2026-05-30T15:00:00-04:00"}]'::jsonb, 'Lumberton Plaza', 'Lumberton, NC', 'Free food. Real hope. No judgment. Free hotdogs, live music, and local testimonies, with Drew Anderson bringing the Word. Alongside 4PointsNorth, The United Worship Band, Cause We Care, and Rock Bottom Ministries.', null),
('pull-up-and-eat-2026', 'Pull Up and Eat', '/images/flyers/pull-up-and-eat-2026.webp', 933, 1400, '[{"start":"2026-04-04T11:00:00-04:00","end":"2026-04-04T14:00:00-04:00"}]'::jsonb, 'Rocky Mount', '341 McDonald St, Rocky Mount, NC', 'Feeding the unhoused community in the park with free food, clothes, Bibles, and prayer, alongside Operation Recovery and Rock Bottom Ministries. If you''re struggling and need a meal, it''s for you.', null),
('serving-the-homeless-2026', 'Serving the Homeless', '/images/flyers/serving-the-homeless-2026.webp', 1050, 1400, '[{"start":"2026-02-21T12:00:00-05:00","end":"2026-02-21T15:00:00-05:00"}]'::jsonb, 'Fayetteville', '128 S King St, Fayetteville, NC 28301', 'Being the hands and feet of Jesus with food, clothing, and prayer, alongside The Restored Table and Rock Bottom Ministries.', null),
('revival-moments-2025', 'Revival Moments & Testimonial Service', '/images/flyers/revival-moments-2025.webp', 1081, 1400, '[{"start":"2025-10-25T11:00:00-04:00"}]'::jsonb, 'Sunshine''s Faith Over Fear Ministries', '605 Depot Street, Rockwell, NC 28138', 'Healing, prayer, worship, and deliverance with Sunshine & SJ, guest speaker Kristy, and Evangelist Brandon Hamilton & Melody. Free food, drinks, and care packages.', null),
('resurrection-bash-2026', 'Resurrection Bash', '/images/flyers/resurrection-bash-2026.webp', 1050, 1400, '[{"start":"2026-03-28T13:00:00-04:00"}]'::jsonb, 'Christ Fellowship Church of Toccoa', '3273 GA-17, Toccoa, GA 30577', 'Egg hunts, crafts, a free meal and food box giveaway, the Resurrection story, and music by #GODGANG & Friends.', null)
